import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createNode as _placeholder } from '@/primitives'; // placeholder to satisfy import list, not used

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Atlas region (hard‑coded for this spec)
  const region = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;

  const group = new Group();

  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial();

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Billboarding: align with camera each frame
  mesh.onBeforeRender = function (_, __, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  // Load texture asynchronously
  let loadedTexture = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;

    const texWidth = tex.image?.width ?? 1;
    const texHeight = tex.image?.height ?? 1;

    const scaleU = region.w / texWidth;
    const scaleV = region.h / texHeight;
    const offsetU = region.x / texWidth;
    const offsetV = region.y / texHeight;

    const uvNode = uv()
      .mul(vec2(scaleU, scaleV))
      .add(vec2(offsetU, offsetV));

    material.colorNode = texture(uvNode, tex);
    material.needsUpdate = true;
  });

  // No primitives or text to apply per spec

  // Handlers placeholder (no interactions)
  group.userData.handlers = {};

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    // Kill any GSAP timelines (none in this node, but precaution)
    gsap.globalTimeline.clear(true);
  };

  // Store promise for potential cancellation (not required by runtime)
  group.userData._texturePromise = texPromise;

  return group;
}
